import{z as n,x as s,o as A,c as o,q as B,j as i,D as a,d as l,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"成本工程","description":"","frontmatter":{"title":"成本工程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-cost-engineering.md","filePath":"llm/diff-cost-engineering.md","lastUpdated":1791063341000}'),d={name:"llm/diff-cost-engineering.md"};function f(p,E,D,m,C,h){const e=s("Mermaid");return A(),o("div",null,[E[2]||(E[2]=B('<h1 id="成本工程" tabindex="-1">成本工程 <a class="header-anchor" href="#成本工程" aria-label="Permalink to &quot;成本工程&quot;">​</a></h1><div class="epigraph"><p>单价的公式早就定了：前向次数乘单次成本除以批效率，再加固定段；成本工程不是砍价，是把公式里每一项变成有人认领的旋钮。</p><footer>—— 据本课程各课的量级与图像生成服务实践整理</footer></div><p><a href="/llm/diff-video-serving">上一课</a>把视频装进作业系统，管好了最贵的负载。本课把前六课的旋钮换成账：图像与视频共用一张单价表，每一项都要能落到人、落到监控、落到预算。蒸馏、量化、调度各自宣布了收益，成本工程的活是让它们在同一个口径下相加。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>图像服务的成本争议几乎都源于口径不一：算法报的是去噪循环的 GPU 时间，财务报的是含空闲与超时的整机账单，产品报的是按请求配额折的虚拟数。三者对不上，优化就成了各说各话。缺口是一张公认的账：<strong>单图成本 =（前向次数 × 单前向成本）÷ 有效批效率 + 固定段成本 + 分摊成本</strong>。前向次数是步数 × 引导倍数（<a href="/llm/diff-serving-pipeline">管线解剖</a>）；单前向成本由精度与实现决定（<a href="/llm/diff-quantization">量化</a>）；有效批效率是凑批率与重编译损耗（<a href="/llm/diff-batching-scheduling">批处理与调度</a>）；固定段是条件装配与解码；分摊是模型常驻显存、空闲与运维。</p>',5)),(A(),i(r,null,{default:a(()=>[t(e,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20GPU%5B%22%E5%90%8C%E4%B8%80%E5%8F%B0%20GPU%20%E7%9A%84%E7%9C%9F%E5%AE%9E%E5%BC%80%E9%94%80%22%5D%20--%3E%20A1%5B%22%E7%AE%97%E6%B3%95%E5%8F%A3%E5%BE%84%3A%20%E5%8F%AA%E5%9B%9E%E5%8E%BB%E5%99%AA%E5%BE%AA%E7%8E%AF%E6%AE%B5%22%5D%0A%20%20GPU%20--%3E%20F1%5B%22%E8%B4%A2%E5%8A%A1%E5%8F%A3%E5%BE%84%3A%20%E6%95%B4%E6%9C%BA%E8%B4%A6%E5%8D%95%3Cbr%2F%3E%E5%90%AB%E7%A9%BA%E9%97%B2%E4%B8%8E%E8%B6%85%E6%97%B6%22%5D%0A%20%20GPU%20--%3E%20P1%5B%22%E4%BA%A7%E5%93%81%E5%8F%A3%E5%BE%84%3A%20%E6%8C%89%E9%85%8D%E9%A2%9D%E6%8A%98%E7%9A%84%E8%99%9A%E6%8B%9F%E6%95%B0%22%5D%0A%20%20A1%20--%3E%20GAP%5B%22%E4%B8%89%E4%B8%AA%E6%95%B0%E6%B0%B8%E8%BF%9C%E5%AF%B9%E4%B8%8D%E4%B8%8A%3Cbr%2F%3E%E4%BC%98%E5%8C%96%E5%8F%98%E6%88%90%E5%90%84%E8%AF%B4%E5%90%84%E8%AF%9D%22%5D%0A%20%20F1%20--%3E%20GAP%0A%20%20P1%20--%3E%20GAP%0A%20%20LED%5B%22%E7%BB%9F%E4%B8%80%E8%B4%A6%E6%9C%AC%3A%20%E6%8C%89%E6%AE%B5%E8%AE%A1%E6%97%B6%20%2B%20%E5%8D%95%E4%BB%B7%E8%A1%A8%22%5D%20-.-%3E%7C%E6%8A%8A%E4%B8%89%E4%B8%AA%E5%8F%A3%E5%BE%84%E9%92%89%E5%88%B0%E5%90%8C%E4%B8%80%E6%A0%BC%7C%20GAP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">代入数字感受公式：50 步 × 引导 2 倍 = 100 次前向；单前向 20 毫秒、批效率 0.5 时，仅循环段每图就是 \\(100\\times20\\mathrm{ms}\\div0.5=4\\) 秒 GPU 时间。把步数档从 50 砍到 30，这一项直接降四成——为什么说前向次数是最大单项，这就是账。</span></p><h3 id="认领旋钮" tabindex="-1">认领旋钮 <a class="header-anchor" href="#认领旋钮" aria-label="Permalink to &quot;认领旋钮&quot;">​</a></h3><ul><li><strong>前向次数</strong>：产品档位决定默认步数与学生/教师分层（<a href="/llm/diff-step-distill-tradeoff">步数蒸馏</a>）；这是最大的单项，也最容易被「默认 50 步」这种惰性配置吃掉。</li><li><strong>单前向成本</strong>：精度分配与算子实现，归推理团队；监控指标是每步时延分布而不是平均值。</li><li><strong>批效率</strong>：桶设计与档位收敛，归调度团队；监控凑批率与重编译次数。</li><li><strong>缓存命中</strong>：条件嵌入、控制图、LoRA 合并缓存，命中率直接从固定段里扣钱。</li><li><strong>常驻与换入换出</strong>：多模型并存时，底座权重是显存常数项；换一次模型是一次冷启动，要么常驻要么排队。</li></ul><p><span class="marginnote">SD 1.5 的 UNet 约 860M 参数，fp16 权重约 1.7 GB：多模型并存时显存的大头是权重常数项而非激活。容量规划先扣权重，再谈批大小——顺序反过来会系统性高估可承载并发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三步立账。第一步，埋点按段计时：条件段、循环段、收尾段、排队与换模型分别落指标，段账与第一课的解剖一一对应。第二步，单价表按（模型档，分辨率档，步数档）三维发布，每个单元格有实测数；工单与容量评审用同一张表，禁止另起口径。第三步，把「每图成本」变成有门禁的 SLO：任何改动合并前要报单价与质量两条增量，口径用本课程评测课的管线，成本与质量同 gate。</p>',6)),(A(),i(r,null,{default:a(()=>[t(e,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E6%8C%89%E6%AE%B5%E5%9F%8B%E7%82%B9%E8%AE%A1%E6%97%B6%22%5D%20--%3E%20LED%5B%22%E8%B4%A6%E6%9C%AC%EF%BC%9A%E5%89%8D%E5%90%91%E6%AC%A1%E6%95%B0%20%C3%97%20%E5%8D%95%E5%89%8D%E5%90%91%20%C3%B7%20%E6%89%B9%E6%95%88%E7%8E%87%22%5D%0A%20%20LED%20--%3E%20FIX%5B%22%E5%9B%BA%E5%AE%9A%E6%AE%B5%EF%BC%9A%E6%9D%A1%E4%BB%B6%E8%A3%85%E9%85%8D%20%2B%20%E8%A7%A3%E7%A0%81%20%2B%20%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%22%5D%0A%20%20FIX%20--%3E%20AMO%5B%22%E5%88%86%E6%91%8A%EF%BC%9A%E6%9D%83%E9%87%8D%E5%B8%B8%E9%A9%BB%20%2B%20%E7%A9%BA%E9%97%B2%20%2B%20%E8%BF%90%E7%BB%B4%22%5D%0A%20%20AMO%20--%3E%20TBL%5B%22%E5%8D%95%E4%BB%B7%E8%A1%A8%EF%BC%9A%E6%A8%A1%E5%9E%8B%E6%A1%A3%20%C3%97%20%E5%88%86%E8%BE%A8%E7%8E%87%E6%A1%A3%20%C3%97%20%E6%AD%A5%E6%95%B0%E6%A1%A3%22%5D%0A%20%20TBL%20--%3E%20GATE%7B%22%E6%94%B9%E5%8A%A8%E9%97%A8%E7%A6%81%22%7D%0A%20%20GATE%20--%3E%7C%E8%B4%A8%E9%87%8F%E8%BF%87%20%2B%20%E5%8D%95%E4%BB%B7%E9%99%8D%E6%88%96%E5%B9%B3%7C%20SHIP%5B%22%E5%90%88%E5%B9%B6%E4%B8%8A%E7%BA%BF%22%5D%0A%20%20GATE%20--%3E%7C%E5%8D%95%E4%BB%B7%E5%8D%87%7C%20REV%5B%22%E5%AE%B9%E9%87%8F%E8%AF%84%E5%AE%A1%E5%86%8D%E8%AE%AE%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么批效率项最难管：它不是单一参数，是桶设计、流量分布与档位数的乘积。流量漂移（用户突然涌向高分辨率档）会让原本健康的桶空转，有效算力先掉一半再谈别的都白搭；所以批效率要按天监控分布，漂移触发档位重审。为什么缓存命中算成本而不是算性能：固定段在批外串行执行，命中的请求不占 GPU 与 CPU 预处理池，等于直接从单价里减常数——命中率是少数「无质量代价的省钱项」，应最先挖。为什么分摊项不可省：底座常驻显存换来了零冷启动，这笔租金属固定成本；按请求均摊后，低峰期单价里有一半可能是空闲——这解释了离线批要填低谷而不是扩容高峰。</p><p><span class="marginnote">分摊项可以类比店面租金：不管今天来几个客人，租金照付。低峰期单价里一半是空闲，等于半夜还开着全部收银台；「离线批填低谷」就是开夜宵档——把固定租金摊给更多订单，而不是高峰期再租一间铺面。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>账本不替代实验：单价表的格子要在自己的硬件与实现上实测，纸面 FLOPs 与厂商峰值折算一律不进表。降本有下限：步数与精度砍到质量门禁以下，省下的是钱、赔掉的是产品；门禁优先级恒高于单价。视频作业的成本沿用同一张表，只是格子乘上帧数项。本课不涉及对外定价：单价表是内部口径，定价还要加毛利与配额策略。最后，成本的归因依赖谱系完整——模型、LoRA、预处理器、精度、桶配置都要在请求落盘，否则单价漂移查不到是哪个旋钮动的。</p><p><span class="marginnote">常见误区：把「纸面 FLOPs 省了 40%」当成账单会省 40%。账本只认实测——单前向 20 毫秒是在特定精度、特定算子实现、特定硬件上量出来的，换一个实现就得重测。让纸面数溜进单价表，正是单价漂移最常见的起点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单价 = 前向次数 × 单前向成本 ÷ 批效率 + 固定段 + 分摊，五项各有认领人。</li><li>最大单项是前向次数：产品档位与师生分层的默认值决定成本基线。</li><li>缓存命中率是无质量代价的省钱项，最先挖；批效率最难管，按天监控漂移。</li><li>权重常驻是显存常数项，容量先扣权重再算并发。</li><li>每图成本与质量同 gate：改动必须报两条增量，成本门禁不得越过质量门禁。</li><li>出处：单价公式与口径据本课程各课整理；参数规格据 Stable Diffusion 公开资料。</li></ul>',8))])}const c=n(d,[["render",f]]);export{g as __pageData,c as default};
